contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        address beforeOwner = c.owner();

        c.transferOwnership(newOwner);

        bool reverted = false;
        address caller = address(0xdead);
        // We cannot change msg.sender, so instead force a non-owner call by first
        // transferring ownership away from this contract, then trying to call again.
        // However, the focus is transferOwnership; do a second transferOwnership
        // from this contract which is no longer the owner after the first call.
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.owner() != newOwner);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner1, address newOwner2) public payable {
        require(newOwner1 != address(0) && newOwner2 != address(0));
        require(newOwner2 != newOwner1);
        require(newOwner2 != address(this));

        c.transferOwnership(newOwner1);

        address ownerAfterFirst = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner2) {
            reverted = false;
        } catch {
            reverted = true;
        }

        address ownerAfterSecond = c.owner();

        assert(reverted && ownerAfterSecond == ownerAfterFirst && ownerAfterFirst == newOwner1);
    }

    receive() external payable {}
}

