contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller, bool useCaller) public {
        require(caller != address(0), "zero caller");

        // The fresh contract has the test contract as its owner because
        // the test contract deployed it. Keep c.owner() as the legitimate
        // owner account and check that the only successful caller is that owner.
        address currentOwner = c.owner();

        bool reverted;

        if (useCaller && caller != currentOwner) {
            // Non-owner caller: `owned()` must revert.
            (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
            reverted = !ok;
            assert(reverted);
        } else {
            // Owner (or the test contract itself): `owned()` must succeed.
            (bool ok, ) = address(c).call(abi.encodeWithSignature("owned()"));
            reverted = !ok;
            assert(!reverted);
        }
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != address(0), "zero caller");

        address currentOwner = c.owner();

        bool reverted;
        if (caller == currentOwner) {
            try c.owned() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.owned() {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        assert(reverted == (caller != currentOwner));
    }
}
